/* Published four-max reference charts. Raked data stays out of no-rake drills. */
let fourHandedReference=null,referenceChartId='pc4-2',chartLibrary='reference';
const referenceColors={Raise:'#a8c977','3-Bet':'#a8c977','4-Bet':'#a8c977',Call:'#647969',Limp:'#79dce4',Check:'#79dce4',Fold:'#303931','Not in range':'#171d19'};
function referenceHandReadout(d,c){if(c.action==='Not in range')return `${c.hand}, when you hold this hand: outside the source’s prior-action range; no action frequency is supplied at this node.`;return `${c.hand}, when you hold this hand: `+Object.keys(d.sourceCombos).map(a=>`${a} ${c.action===a?'100':'0'}%`).join(' · ')}
function chartLibraryPicker(){return `<div class="choices" role="group" aria-label="Four-handed chart library"><button data-chart-library="reference" class="${chartLibrary==='reference'?'selected':''}">Published 4-max reference · raked</button><button data-chart-library="solver" class="${chartLibrary==='solver'?'selected':''}">Imported no-rake solver grids</button></div>`}
function referenceChecks(d){const counts={};for(const c of d.cells)if(c.action!=='Not in range')counts[c.action]=(counts[c.action]||0)+combo(c.hand);return Object.entries(d.sourceCombos).every(([a,n])=>(counts[a]||0)===n)&&Object.values(counts).reduce((a,b)=>a+b,0)===d.nodeCombos}
function referenceCharts(){
 if(!fourHandedReference){shell(`<div class="page"><h1>Four-handed charts.</h1><p>The published reference could not load. Reconnect and reload.</p>${chartLibraryPicker()}</div>`,'Charts');return}
 const {source,charts}=fourHandedReference,d=charts.find(d=>d.id===referenceChartId)||charts[0];referenceChartId=d.id;
 const actions=[...Object.keys(d.sourceCombos),...(d.nodeCombos<1326?['Not in range']:[])],rfi=charts.find(c=>c.hero==='SB'&&c.spot==='RFI'),limpCombos=rfi.sourceCombos.Limp;
 shell(`<div class="page"><div class="eyebrow">Four seats. A published starting point.</div><h1>Four-handed ranges.</h1><p class="muted">CO · BTN · SB · BB · 100bb cash · no ante</p>${chartLibraryPicker()}<aside class="notice"><strong>Reference only: ${source.rakePct}% rake, capped at ${source.rakeCapBb}bb.</strong> These PokerCoaching charts simplify GTO into one action per hand. Your drills use a no-rake baseline, so this reference does not supply drill answers or replace imported solver grids.</aside><div class="chart-pickers"><label>Spot<select id="reference-spot">${[...new Set(charts.map(c=>c.spot))].map(s=>`<option value="${esc(s)}" ${s===d.spot?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Matchup<select id="reference-chart">${charts.filter(c=>c.spot===d.spot).map(c=>`<option value="${c.id}" ${c.id===d.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label></div><section class="panel"><h3>${esc(d.title)} · 4-handed</h3><p class="source">Published four-handed reference · simplified GTO · ${esc(source.publisher)}</p><div class="grid reference-grid" aria-label="${esc(d.title)} hand actions">${d.cells.map(c=>`<button class="cell ${c.action==='Not in range'?'outside-range':''}" style="background:${referenceColors[c.action]};color:${['Raise','3-Bet','4-Bet','Limp','Check'].includes(c.action)?'#14200e':'#e4e9dc'}" data-reference-cell="${c.hand}" aria-label="${esc(referenceHandReadout(d,c))}">${c.hand}</button>`).join('')}</div><div class="legend">${actions.map(a=>`<span><i style="background:${referenceColors[a]}"></i>${a}</span>`).join('')}</div><div class="grid-info" id="reference-hand-info">Tap any hand to see what to do when you hold this hand.</div><p class="source">${d.nodeCombos<1326?'Dim cells are outside the prior-action range, not a fold instruction.':'Pairs on diagonal · suited above · offsuit below.'} Published actions are pure choices; these charts do not provide mixed solver frequencies.</p><div class="checks">${Object.entries(d.sourceCombos).map(([a,n])=>`<p>Whole range: ${a} ${(n/1326*100).toFixed(2)}% of all hands dealt in this seat (${n} / 1,326 combinations).${d.nodeCombos<1326?` At this decision: ${a} ${(n/d.nodeCombos*100).toFixed(2)}% of hands in the source’s prior-action range (${n} / ${d.nodeCombos} combinations).`:''}</p>`).join('')}</div>${d.id==='pc4-16'?`<p class="notice">Source inconsistency: the SB opening chart lists ${limpCombos} limp combinations, while this response chart contains ${d.nodeCombos}. Both are reproduced as published; no hands were added to reconcile them.</p>`:''}<p class="source">${source.publisher} · <a href="${source.url}#page=${d.sourcePage}" target="_blank" rel="noopener noreferrer">Source PDF, page ${d.sourcePage}</a> · <a href="${source.listingUrl}" target="_blank" rel="noopener noreferrer">Publisher’s chart listing</a></p></section><details class="panel"><summary>Source sizing and assumptions</summary><p>100bb cash · no ante · ${source.rakePct}% rake, ${source.rakeCapBb}bb cap.</p><p>Open ${source.openBb}bb, or ${source.sbOpenBb}bb from SB. In-position 3-bet ${source.ipThreeBetBb}bb; out-of-position ${source.oopThreeBetBb}bb. 4-bet ${source.fourBetBb}bb; 5-bet all-in. BB raises a SB limp to ${source.sbLimpRaiseBb}bb, and 3-bets a SB open to ${source.bbVsSbThreeBetBb}bb.</p><p class="source">A no-rake solver export can differ. The app makes no numerical adjustments to the published hands.</p></details><details class="panel"><summary class="check-good">${charts.every(referenceChecks)?'✓':'!'} ${charts.length} grids checked against source combination totals</summary><p class="source">Each grid contains all 169 hand classes. Frequencies and range-wide percentages are derived from the published cell actions with pair = 6, suited = 4, offsuit = 12 combinations.</p>${charts.map(c=>`<div class="stats-row"><span>${esc(c.title)}</span><span>${referenceChecks(c)?'Pass':'Mismatch'} · ${c.nodeCombos} node combinations</span></div>`).join('')}</details></div>`,'Charts');
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.chartLibrary){chartLibrary=b.dataset.chartLibrary;charts()}if(b.dataset.referenceCell){const d=fourHandedReference.charts.find(d=>d.id===referenceChartId),c=d.cells.find(c=>c.hand===b.dataset.referenceCell);document.getElementById('reference-hand-info').textContent=referenceHandReadout(d,c);document.querySelectorAll('.reference-grid .highlight').forEach(c=>c.classList.remove('highlight'));b.classList.add('highlight')}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='reference-chart'){referenceChartId=t.value;referenceCharts()}if(t.id==='reference-spot'){referenceChartId=fourHandedReference.charts.find(c=>c.spot===t.value).id;referenceCharts()}});
